package com.resolveAi.resolveai_backend.order.entity;import com.resolveAi.resolveai_backend.common.entity.BaseEntity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name = "order_items")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class OrderItem extends BaseEntity {        @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "order_id", nullable = false)    private Order order;    private String productName;    private String sku;    private Integer quantity;        @Column(precision = 15, scale = 2)    private BigDecimal unitPrice;        @Column(precision = 15, scale = 2)    private BigDecimal totalPrice;}